import{_ as a,o,c as t,a2 as s}from"./chunks/framework.lvJarkfX.js";const u=JSON.parse('{"title":"A06 — Account Access API","description":"","frontmatter":{},"headers":[],"relativePath":"02-plataforma/a06.md","filePath":"02-plataforma/a06.md"}'),r={name:"02-plataforma/a06.md"};function c(i,e,n,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="a06-—-account-access-api" tabindex="-1">A06 — Account Access API <a class="header-anchor" href="#a06-—-account-access-api" aria-label="Permalink to &quot;A06 — Account Access API&quot;">​</a></h1><p><strong>Volume:</strong> Plataforma e core · <strong>Capítulo:</strong> A06 · <strong>Fonte catalogada:</strong> <code>apps/account-access-api</code></p><blockquote><p><strong>Protótipo editorial:</strong> os trechos seguintes são derivados dos arquivos versionados; existência de código não significa homologação.</p></blockquote><h2 id="ficha-uniforme-do-capitulo" tabindex="-1">Ficha uniforme do capítulo <a class="header-anchor" href="#ficha-uniforme-do-capitulo" aria-label="Permalink to &quot;Ficha uniforme do capítulo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Referência</th></tr></thead><tbody><tr><td>Código e owner</td><td><code>A06</code> · <code>apps/account-access-api</code></td></tr><tr><td>Estado declarado</td><td><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/STATUS.md" target="_blank" rel="noreferrer">STATUS no repositório</a></td></tr><tr><td>Contratos, classes e APIs</td><td><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/REFERENCIA-TECNICA.md" target="_blank" rel="noreferrer">Referência técnica</a></td></tr><tr><td>Implantação e operação</td><td><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/OPERACAO.md" target="_blank" rel="noreferrer">Operação</a></td></tr></tbody></table><h2 id="_1-estado-documentado" tabindex="-1">1. Estado documentado <a class="header-anchor" href="#_1-estado-documentado" aria-label="Permalink to &quot;1. Estado documentado&quot;">​</a></h2><blockquote><p><strong>AUDITORIA TÉCNICA PARCIAL — 13/11/2026</strong>. Código de7b065; testes Node isolados <strong>10/10 aprovados</strong>. <strong>NÃO HOMOLOGADO</strong>: PostgreSQL 17, OpenFGA, Keycloak, OpenBao e deploy reais não verificados. - HTTP: createAccountAccessServer oferece GET /healthz, GET /readyz e POST /v1/accounts/{tenantUuid}/access/delegations; oito testes mockados passaram. - Auth: createTokenVerifier usa RS256/JWKS, issuer/audience/azp dedicado; createFgaWriteAuthorizer exige can_write em recurso tenant-scoped; dois testes passaram. - SQL: control-account-roles.schema e control-account-delegation.schema definem apply_tenant_account_delegation e proteção de último owner. Inspeção estática, sem PG17. - Startup: exige login syndes_account_api, não criado automaticamente pela migration. | ID | Estado | Gate | |---|---|---| | A06.DOC.01 | AUDITORIA PARCIAL | Contratos e evidências vinculados | | A06.SQL.01 | PENDENTE | PG17 descartável, A/B, idempotência, último owne …</p></blockquote><h2 id="_2-contratos-apis-metodos-e-dados" tabindex="-1">2. Contratos, APIs, métodos e dados <a class="header-anchor" href="#_2-contratos-apis-metodos-e-dados" aria-label="Permalink to &quot;2. Contratos, APIs, métodos e dados&quot;">​</a></h2><blockquote><p>Auditoria estática de código de7b065; testes Node 10/10 em ambiente descartável, sem integração real. Node ESM &gt;=22, jose 6.0.11, pg 8.16.3. Serviço backend de delegação owner/admin, sem frontend, CRM, Inbox ou proxy genérico. C01 é owner do Control, C03 da identidade, C04 da autorização, C05 dos segredos. - GET /healthz: liveness 200 sem dependências. - GET /readyz: 200/503, verifica presença da função SQL. - POST /v1/accounts/{tenantUuid}/access/delegations: exige Origin HTTPS exata, Bearer, Idempotency-Key UUID, Content-Type JSON, body até 2048 bytes com operation grant/revoke, principalId e role owner/admin; retorna role, state, alreadyApplied. Respostas de erro sanitizadas. | Símbolo | Fonte | Responsabilidade | |---|---|---| | createAccountAccessServer | src/server.mjs | Factory HTTP exportada, injeta verificador, autorização e delegação | | createTokenVerifier | src/auth.mjs | Export JWKS RS256, issuer, audience, azp, subject | | fgaObject | src/auth.mjs | Export resource:sha256(tenantId e resource) | | createFgaWriteAuthorizer | src/auth.mjs | Export can_write tenant-scoped, timeout 3s | | bodyObject | src/server.mjs | Parser privado de JSON | | credentialFromFile | src/main.mjs | Helper privado, Control URL em /run/secr …</p></blockquote><h2 id="_3-operacao-e-evidencias" tabindex="-1">3. Operação e evidências <a class="header-anchor" href="#_3-operacao-e-evidencias" aria-label="Permalink to &quot;3. Operação e evidências&quot;">​</a></h2><p>&gt; Checklist de auditoria, não runbook homologado. Nenhuma migration, role, segredo ou serviço foi alterado. A primeira tentativa npm test falhou por dependência ausente (ERR_MODULE_NOT_FOUND). Após npm ci em /tmp descartável, os 10 testes Node passaram. Isso não valida banco ou implantação. 1. PostgreSQL 17 descartável: grants, EXECUTE, tenant A/B, último owner, idempotência e replay. 2. Validar role syndes_account_api, JWT/JWKS, OpenFGA e secrets em ambiente autorizado sem ler valores. 3. Validar readiness, ingress, logs, backup, rollback e CI por SHA. 4. Sign-off C01/C03/C04/C05/A06 e segurança. · · · · · · .</p><h2 id="_4-secoes-de-referencia" tabindex="-1">4. Seções de referência <a class="header-anchor" href="#_4-secoes-de-referencia" aria-label="Permalink to &quot;4. Seções de referência&quot;">​</a></h2><ul><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/01-missao-objetivos-e-fronteiras.md" target="_blank" rel="noreferrer">Missão e limites</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/02-requisitos-historias-e-casos-de-uso.md" target="_blank" rel="noreferrer">Requisitos e casos de uso</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/03-capabilities.md" target="_blank" rel="noreferrer">Capacidades</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/04-contratos-e-dependencias-publicas.md" target="_blank" rel="noreferrer">Contratos públicos e dependências</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/05-arquitetura-banco-interface-configuracao-e-diagramas.md" target="_blank" rel="noreferrer">Arquitetura, SQL, APIs e interface</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/06-wbs-marcos-e-aceite.md" target="_blank" rel="noreferrer">WBS e aceitação</a></li><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/chapters/07-controle-do-escopo.md" target="_blank" rel="noreferrer">Controle de escopo</a></li></ul><h2 id="_5-fontes-cruzadas" tabindex="-1">5. Fontes cruzadas <a class="header-anchor" href="#_5-fontes-cruzadas" aria-label="Permalink to &quot;5. Fontes cruzadas&quot;">​</a></h2><ul><li><a href="https://github.com/delmacy/syndes-system/blob/main/docs/subprojects/A06-account-access-api/README.md" target="_blank" rel="noreferrer">Módulo no catálogo</a></li><li><a href="https://github.com/delmacy/syndes-system/tree/main/apps/account-access-api" target="_blank" rel="noreferrer">Código de origem no GitHub</a></li></ul><hr><p><em>Ficha gerada para comparação A/B; não substitui os documentos canônicos.</em></p>',17)])])}const h=a(r,[["render",c]]);export{u as __pageData,h as default};
